const backupDir = (msg.payload || {}).backup_dir;
if (!backupDir || backupDir.indexOf('EDIT_ME') !== -1) {
    node.error('backup_dir not set — edit the trigger node\'s payload before clicking (same pattern as oura_backfill_flow.json).', msg);
    return null;
}
msg.backup_dir = backupDir;
flow.set('wdr_backup_dir', backupDir);
return msg;

let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
flow.set('wdr_secrets', secrets);
flow.set('wdr_job_started_at', msg.job_started_at);
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=wherewhen_restore,status=started value=1 ' + nowNs;
return msg;

let manifest = {};
try {
    manifest = JSON.parse(msg.payload);
} catch (e) {
    node.warn('Could not parse manifest.json (' + e.message + ') — verify mode will be skipped, restore still proceeds from whatever CSVs are present.');
}
flow.set('wdr_manifest', manifest);
msg.payload = 'ls -1 ' + flow.get('wdr_backup_dir') + '/*.csv';
return msg;

const files = (msg.payload || '').split('\n').map(s => s.trim()).filter(Boolean);
msg.secrets = flow.get('wdr_secrets');
msg.job_started_at = flow.get('wdr_job_started_at');
if (!files.length) {
    node.warn('No CSV files found in ' + flow.get('wdr_backup_dir') + ' — nothing to restore.');
    return [null, msg];
}
msg.files = files;
return [msg, null];

// Manual fan-out, not Node-RED's core `split` node -- real bug,
// Aug 2026: the generic split node failed to correctly isolate each
// array element when targeting a custom-named message property
// (confirmed via wherewhen_data_export_flow.json's own diagnostic
// node.warn output on Ward's real instance -- every downstream
// message was receiving the same unrelated raw text instead of its
// own array element). The one split node in this project using the
// DEFAULT "payload" property (analysis_engine_flow.json's
// n_ae_split) is confirmed working via real usage, which is what
// narrowed this down to custom-property targeting specifically,
// not split() in general. msg.parts is built by hand to match
// exactly what Node-RED's own split node documents, so the paired
// join node (mode: "auto") downstream needs no changes.
const items = msg.files || [];
const batchId = 'batch_' + Date.now() + '_' + Math.random().toString(36).slice(2);
// Wrapped in an EXTRA array layer -- real bug caught, Aug 2026: a
// function node with a SINGLE output that returns a flat array of
// messages has that array interpreted as "one message per output
// port," so with only 1 output Node-RED took just the first message
// and silently dropped the rest (confirmed: exactly one file -- the
// first measurement -- was ever written, no error). [[...]] is the
// documented way to send many messages down ONE output: the outer
// array is per-output-port, the inner array is the messages for that
// port.
return [items.map((item, i) => {
    const m = Object.assign({}, msg, { payload: item });
    m.parts = { id: batchId, type: 'array', index: i, count: items.length };
    return m;
})];

// THE RISKIEST LOGIC IN THIS FLOW — see this tab's own info note for
// the full explanation. KNOWN LIMITATION, not yet handled: this splits
// each CSV row on plain ',' — it does NOT handle RFC4180-style quoted
// fields that contain a literal comma inside a value (e.g. a string
// field value like 'a, b'). None of this project's actual field values
// are expected to contain commas today, so this is a real but currently-
// low-risk simplification — worth fixing with a proper CSV-quote-aware
// split if that ever stops being true. Handles multiple table/header blocks in one
// response (Flux groups different tag-combinations under one measurement
// into separate annotated blocks, separated by a blank line) by
// re-detecting a new header row whenever one appears. BUG FIX (Aug 2026,
// Fulgrim Flux-engine pass): the original heuristic here re-detected a
// header only when the row differed from the previous one (a helper
// array-equality check, since removed) — which silently misparsed a
// REPEATED identical header row as a data row instead. That happens routinely in real Flux
// output: two consecutive table blocks with the same tag SET but
// different tag VALUES produce byte-identical header rows. Fixed by
// requiring all three reserved markers ('_measurement', '_field',
// '_value') as literal cell values on the SAME row, dropping the
// differs-from-previous check entirely — real data will essentially
// never carry all three of those exact strings as its own
// field/measurement/tag values, so this is strictly safer, not riskier,
// than the one-marker version it replaces. In THIS flow specifically the
// old bug was low-impact in practice — the resulting phantom row's _time
// value is literally the string "_time", which fails the NaN-timestamp
// check further down and gets silently dropped, and a same-header-text
// block's real data rows still parse fine against the stale (but
// identical) header object. Fixed anyway rather than relying on that
// incidental self-correction, and because the new analysis-engine flow
// (analysis_engine_flow.json) adapts this same parser into one that
// outputs row objects instead of line-protocol, without that downstream
// NaN filter — there, the same bug would have silently fed a garbage row
// into real analysis math instead of being dropped.
function esc(s) { return String(s).replace(/([ ,=])/g, '\\$1'); }

function parseFluxCsvToLines(csvText) {
    const RESERVED = new Set(['result', 'table', '_start', '_stop', '_time', '_value', '_field', '_measurement']);
    const rawLines = csvText.split('\n').map(l => l.replace(/\r$/, ''));
    let header = null;
    const outLines = [];
    let dataRowCount = 0;

    rawLines.forEach(raw => {
        if (raw === '') { return; } // blank separator between table blocks — next real row re-detects header
        if (raw.startsWith('#')) return; // #datatype/#group/#default — not needed to reconstruct line protocol
        const cols = raw.split(',');
        if (cols.includes('_measurement') && cols.includes('_field') && cols.includes('_value')) {
            header = cols;
            return;
        }
        if (!header) return; // stray row before any header seen — skip rather than crash the whole restore
        if (cols.length !== header.length) return; // malformed/short row — same reasoning

        const row = {};
        header.forEach((colName, i) => { row[colName] = cols[i]; });

        const measurement = row['_measurement'];
        const field = row['_field'];
        const value = row['_value'];
        const time = row['_time'];
        if (!measurement || !field || value === undefined || value === '' || !time) return;

        const tsMs = new Date(time).getTime();
        if (!Number.isFinite(tsMs)) return;

        const tagParts = [];
        header.forEach(colName => {
            if (!RESERVED.has(colName) && colName !== '' && row[colName] !== undefined && row[colName] !== '') {
                tagParts.push(esc(colName) + '=' + esc(row[colName]));
            }
        });

        const isNumeric = !isNaN(Number(value));
        const fieldPart = esc(field) + '=' + (isNumeric ? Number(value) : ('"' + String(value).replace(/"/g, '') + '"'));
        const tagStr = tagParts.length ? ',' + tagParts.join(',') : '';

        outLines.push(esc(measurement) + tagStr + ' ' + fieldPart + ' ' + (tsMs * 1000000));
        dataRowCount++;
    });

    return { lines: outLines, dataRowCount };
}

const parsed = parseFluxCsvToLines(msg.payload || '');
msg.measurement_name = (msg.filename || '').split('/').pop().replace(/\.csv$/, '');
msg.restored_line_count = parsed.lines.length;

const secrets = flow.get('wdr_secrets');
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = parsed.lines.join('\n');
return msg;

const manifest = flow.get('wdr_manifest') || {};
const measurements = Array.isArray(manifest.measurements) ? manifest.measurements : [];
msg.secrets = flow.get('wdr_secrets');
msg.job_started_at = flow.get('wdr_job_started_at');
msg.total_lines_restored = Array.isArray(msg.payload) ? msg.payload.reduce((a, b) => a + (b || 0), 0) : 0;
flow.set('wdr_total_lines_restored', msg.total_lines_restored);
if (!measurements.length) {
    msg.verify_results = [];
    return [null, msg];
}
msg.measurements = measurements;
return [msg, null];

// Manual fan-out, not Node-RED's core `split` node -- real bug,
// Aug 2026: the generic split node failed to correctly isolate each
// array element when targeting a custom-named message property
// (confirmed via wherewhen_data_export_flow.json's own diagnostic
// node.warn output on Ward's real instance -- every downstream
// message was receiving the same unrelated raw text instead of its
// own array element). The one split node in this project using the
// DEFAULT "payload" property (analysis_engine_flow.json's
// n_ae_split) is confirmed working via real usage, which is what
// narrowed this down to custom-property targeting specifically,
// not split() in general. msg.parts is built by hand to match
// exactly what Node-RED's own split node documents, so the paired
// join node (mode: "auto") downstream needs no changes.
const items = msg.measurements || [];
const batchId = 'batch_' + Date.now() + '_' + Math.random().toString(36).slice(2);
// Wrapped in an EXTRA array layer -- real bug caught, Aug 2026: a
// function node with a SINGLE output that returns a flat array of
// messages has that array interpreted as "one message per output
// port," so with only 1 output Node-RED took just the first message
// and silently dropped the rest (confirmed: exactly one file -- the
// first measurement -- was ever written, no error). [[...]] is the
// documented way to send many messages down ONE output: the outer
// array is per-output-port, the inner array is the messages for that
// port.
return [items.map((item, i) => {
    const m = Object.assign({}, msg, { payload: item });
    m.parts = { id: batchId, type: 'array', index: i, count: items.length };
    return m;
})];

const secrets = flow.get('wdr_secrets');
const measurement = msg.payload;
msg.measurement_name = measurement;
const flux = 'from(bucket: "' + secrets.influxdb_bucket + '") |> range(start: 0) |> filter(fn: (r) => r._measurement == "' + measurement.replace(/"/g, '\\"') + '") |> count()';
msg.url = secrets.influxdb_url + '/api/v2/query?org=' + encodeURIComponent(secrets.influxdb_org);
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'application/vnd.flux', 'Accept': 'application/csv' };
msg.payload = flux;
return msg;

const text = msg.payload || '';
const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
const headerLine = lines.find(l => !l.startsWith('#'));
let count = null;
if (headerLine) {
    const cols = headerLine.split(',');
    const valueIdx = cols.indexOf('_value');
    const dataLine = lines[lines.indexOf(headerLine) + 1];
    if (dataLine && valueIdx !== -1) count = parseInt(dataLine.split(',')[valueIdx], 10);
}
return { payload: { measurement: msg.measurement_name, post_restore_count: (Number.isFinite(count) ? count : null) } };

// BALLPARK sanity check, per this tab's own info note — manifest
// row_count includes CSV header/annotation lines from the export side,
// so exact equality against post-restore point counts isn't expected.
// This flags LARGE discrepancies (a wrong order of magnitude, or zero
// when something was expected), not small ones.
const manifest = flow.get('wdr_manifest') || {};
const results = Array.isArray(msg.payload) ? msg.payload : [];
const manifestByName = {};
(manifest.measurements || []).forEach(m => { manifestByName[m] = true; });

const warnings = [];
results.forEach(r => {
    if (r.post_restore_count === null) {
        warnings.push(r.measurement + ': could not read a post-restore count (verify query itself may need checking).');
    } else if (r.post_restore_count === 0) {
        warnings.push(r.measurement + ': 0 points found after restore — likely means this measurement\'s write failed or its CSV was empty.');
    }
});

msg.verify_results = results;
msg.verify_warnings = warnings;
msg.secrets = flow.get('wdr_secrets');
msg.job_started_at = flow.get('wdr_job_started_at');
msg.total_lines_restored = flow.get('wdr_total_lines_restored') || 0;
if (warnings.length) {
    node.warn('Restore verify pass found ' + warnings.length + ' issue(s): ' + warnings.join(' | '));
}
return msg;

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at || Date.now()).getTime();
const warnCount = (msg.verify_warnings || []).length;
msg.influx_finish_point = 'sync_job_runs,job_name=wherewhen_restore,status=success total_lines_restored=' + (msg.total_lines_restored || 0) + ',verify_warning_count=' + warnCount + ',duration_ms=' + durationMs + ' ' + nowNs;
msg.sqlite_job = { job_name: 'wherewhen_restore', mode: 'success', last_success: new Date().toISOString(), last_attempt: new Date().toISOString(), last_attempt_ok: warnCount ? 0 : 1 };
if (!msg.secrets) msg.secrets = flow.get('wdr_secrets');
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

const nowNs = Date.now() * 1000000;
const detail = ((msg.error && msg.error.message) || 'unknown error').toString();
const source = (msg.error && msg.error.source && msg.error.source.name) || 'unknown node';
const safeDetail = (source + ': ' + detail).replace(/([ ,="])/g, '\\$1');
msg.secrets = flow.get('wdr_secrets');
msg.job_started_at = flow.get('wdr_job_started_at');
msg.influx_finish_point = 'sync_job_runs,job_name=wherewhen_restore,status=failed,failure_code=flow_error detail="' + safeDetail + '" ' + nowNs;
msg.sqlite_job = { job_name: 'wherewhen_restore', mode: 'failure', last_attempt: new Date().toISOString(), last_attempt_ok: 0, last_error: (source + ': ' + detail).slice(0, 250) };
node.warn('wherewhen Data Restore failed: ' + source + ': ' + detail);
return msg;

// Ensures the shared status table exists before every write — cheap
// no-op if it already does. Same idempotent CREATE TABLE IF NOT EXISTS
// discipline as godaddy/sql/upgrade_from_3.0.0.sql, just run inline
// rather than as a separate manual step (Ward, Aug 2026 — "a node red
// task that initializes it, and keeps it up to date"). Identical in
// every flow that writes status — duplicated on purpose, matching this
// project's existing preference for self-contained nodes over a shared-
// context module pattern.
msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

// Builds the UPSERT from msg.sqlite_job (set by job_success/job_failed
// above). 'success' mode updates last_success and clears last_error;
// 'failure' mode updates last_error and deliberately leaves last_success
// untouched (a failure shouldn't erase the last known-good run). checkpoint
// is job-specific optional state (only oura_sync uses it, for its self-heal
// fetch window) — only touched when the caller actually supplies one.
function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
    if (j.checkpoint !== undefined && j.checkpoint !== null) setClauses.push('checkpoint=excluded.checkpoint');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;
